const body = $json.body ?? $json;
const slug = (body.project_slug ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!slug) throw new Error('project_slug is required in the JSON body.');
const extra = (body.extra_direction ?? '').toString().trim();
return [{ json: { slug, extra_direction: extra } }];

const res = $json;
if (!res.ok) throw new Error(res.error || 'Failed to load project story.');
const story = (res.story ?? '').toString().trim();
const extra = (res.extra_direction ?? '').toString().trim();
const title = (res.title ?? 'Untitled').toString();
const words = story.split(/\s+/).filter(Boolean).length;
const targetShots = Math.min(48, Math.max(6, Math.round(words / 12)));
const VOICES = ['zephyr', 'puck', 'charon', 'kore', 'fenrir', 'leda', 'orus', 'aoede', 'callirrhoe', 'autonoe', 'enceladus', 'iapetus', 'umbriel', 'algieba', 'despina', 'erinome', 'algenib', 'rasalgethi', 'laomedeia', 'achernar', 'alnilam', 'schedar', 'gacrux', 'pulcherrima', 'achird', 'zubenelgenubi', 'vindemiatrix', 'sadachbia', 'sadaltager', 'sulafat'];
const TTS_DEFAULT = 'google/gemini-3.1-flash-tts-preview';

let prompt = [
'You are a film script writer and storyboard artist. Convert the story below into a shot-by-shot script.',
'',
'RULES:',
'- Return ONLY strict JSON. No markdown fences, no commentary.',
'- Aim for about ' + targetShots + ' shots in total (story length: ' + words + ' words). Scale the shot count to the story — never cram a long story into too few shots. Group shots into scenes of 2 to 6.',
'- CHARACTER CONSISTENCY (critical): each character gets ONE locked character sheet in visual_description that is reused verbatim for every image. Write it as a single 40-80 word paragraph in fixed order: age, face, hair, build, signature clothing and accessories. Never vary or re-describe it between shots.',
'- Keep the cast small and stable: reuse the same character ids across shots; never invent lookalike variants of a character.',
'- Each character: id (snake_case), name, visual_description (the locked character sheet), reference_images (empty array), voice (a TTS voice name from: ' + VOICES.join(', ') + ' — pick a distinct voice per character that fits their age and personality), tts_model ("google/gemini-3.1-flash-tts-preview" unless the author named another OpenRouter TTS model), tts_instructions (short delivery direction, e.g. "warm, gravelly, unhurried").',
'- Write ALL narration and dialogue in the SAME LANGUAGE as the story below.',
'- Each shot: id ("shot_001" style, sequential across scenes), image_prompt (self-contained English description of ONE 16:9 frame; refer to characters by name and keep wardrobe, hair and props consistent with their locked character sheet), characters (array of character ids present, may be empty for scenery), narration (string or null) OR dialogue (array of {character, text}), duration_hint_sec (3 to 12), motion ("auto").',
'- A shot has EITHER narration or dialogue, never both. Lines must be under 240 characters each.',
'- Top level also: title, language (BCP-47 code matching the story language, e.g. "en", "ko"), style_notes (visual style for image generation), narrator_voice (from the voice list), narrator_instructions.',
'',
'SCHEMA:',
'{"title":string,"slug":string,"language":string,"style_notes":string,"narrator_voice":string,"narrator_instructions":string,"characters":[{"id":string,"name":string,"visual_description":string,"reference_images":[],"voice":string,"tts_model":string,"tts_instructions":string}],"scenes":[{"id":string,"title":string,"shots":[{"id":string,"image_prompt":string,"characters":[string],"narration":string|null,"dialogue":[{"character":string,"text":string}],"duration_hint_sec":number,"motion":"auto"}]}]}',
'',
'Set the top-level "slug" exactly to: ' + res.slug,
'STORY TITLE: ' + title,
'STORY:',
story,
].join('\n');
if (extra) prompt += '\n\nEXTRA DIRECTION FROM THE AUTHOR (follow it):\n' + extra;

return [{ json: { slug: res.slug, title, prompt } }];

const slug = $('Build Script Prompt').first().json.slug;
const raw = ($json.output ?? '').toString().trim();
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
let s;
try { s = JSON.parse(cleaned); } catch (e) {
  throw new Error('Script output was not valid JSON: ' + raw.slice(0, 300));
}
const VOICES = new Set(['zephyr', 'puck', 'charon', 'kore', 'fenrir', 'leda', 'orus', 'aoede', 'callirrhoe', 'autonoe', 'enceladus', 'iapetus', 'umbriel', 'algieba', 'despina', 'erinome', 'algenib', 'rasalgethi', 'laomedeia', 'achernar', 'alnilam', 'schedar', 'gacrux', 'pulcherrima', 'achird', 'zubenelgenubi', 'vindemiatrix', 'sadachbia', 'sadaltager', 'sulafat']);
const TTS_DEFAULT = 'google/gemini-3.1-flash-tts-preview';
const TTS_MODEL_RE = /^[a-z0-9][a-z0-9/_.:-]{2,80}$/i;
const okModel = (m) => TTS_MODEL_RE.test((m ?? '').toString().trim());
const charsIn = Array.isArray(s.characters) ? s.characters : [];
const charMap = {};
charsIn.forEach((c, i) => {
  const id = (c.id ?? 'char_' + (i + 1)).toString().toLowerCase().replace(/[^a-z0-9_]/g, '_') || ('char_' + (i + 1));
  charMap[id] = {
    id,
    name: (c.name ?? id).toString(),
    visual_description: (c.visual_description ?? '').toString(),
    reference_images: [],
    voice: VOICES.has((c.voice ?? '').toString().toLowerCase()) ? c.voice.toString().toLowerCase() : 'kore',
    tts_model: okModel(c.tts_model) ? c.tts_model.toString().trim() : TTS_DEFAULT,
    tts_instructions: (c.tts_instructions ?? '').toString().slice(0, 500),
  };
});
const scenes = [];
let n = 0;
for (const sc of (Array.isArray(s.scenes) ? s.scenes : [])) {
  const shots = [];
  for (const sh of (Array.isArray(sc.shots) ? sc.shots : [])) {
    const imagePrompt = (sh.image_prompt ?? '').toString().trim();
    if (!imagePrompt) continue;
    const narration = sh.narration ? sh.narration.toString().trim() : null;
    let dialogue = Array.isArray(sh.dialogue)
      ? sh.dialogue.map((d) => ({
          character: (d.character ?? '').toString().toLowerCase().replace(/[^a-z0-9_]/g, '_'),
          text: (d.text ?? '').toString().trim(),
        })).filter((d) => d.text)
      : [];
    n += 1;
    const dur = Number(sh.duration_hint_sec);
    shots.push({
      id: 'shot_' + String(n).padStart(3, '0'),
      image_prompt: imagePrompt,
      characters: Array.isArray(sh.characters) ? sh.characters.map((x) => x.toString().toLowerCase().replace(/[^a-z0-9_]/g, '_')) : [],
      narration: narration || null,
      dialogue,
      duration_hint_sec: Math.min(15, Math.max(2, Number.isFinite(dur) && dur > 0 ? dur : 5)),
      motion: ['zoom_in', 'zoom_out', 'pan_left', 'pan_right'].includes(sh.motion) ? sh.motion : 'auto',
    });
  }
  if (shots.length) scenes.push({ id: 'scene_' + (scenes.length + 1), title: (sc.title ?? '').toString(), shots });
}
if (!scenes.length) throw new Error('Parsed script contains no usable shots.');
const script = {
  title: (s.title ?? 'Untitled').toString(),
  slug,
  language: ((s.language ?? 'en').toString().slice(0, 12)) || 'en',
  aspect: '16:9',
  fps: 25,
  resolution: '1920x1080',
  style_notes: (s.style_notes ?? '').toString(),
  narrator_voice: VOICES.has((s.narrator_voice ?? '').toString().toLowerCase()) ? s.narrator_voice.toString().toLowerCase() : 'charon',
  narrator_instructions: (s.narrator_instructions ?? '').toString(),
  characters: Object.values(charMap),
  scenes,
};
return [{ json: { slug, shotCount: n, script } }];

const srcs = $('Build Portrait Request').all();
const out = [];
for (let i = 0; i < srcs.length; i++) {
  const src = srcs[i].json;
  const resp = (items[i] && items[i].json) ?? {};
  const arr = Array.isArray(resp.data) ? resp.data : [];
  const img = arr.find((d) => d && d.b64_json);
  if (!img) {
    const reason = (resp.error && (resp.error.message || resp.error.code)) || 'no image in OpenRouter response';
    out.push({ json: { slug: src.slug, charId: src.charId, ok: false, error: String(reason).slice(0, 300) } });
    continue;
  }
  out.push({ json: { slug: src.slug, charId: src.charId, ok: true, imageB64: img.b64_json } });
}
return out;

