import base64, datetime, json, os, subprocess
first = _items[0]["json"] if _items else {}
slug = first.get("slug")
if not slug:
    raise RuntimeError("no portrait results received")
root = "/home/node/files/films/" + slug
anchors_dir = os.path.join(root, "refs", "anchors")
os.makedirs(anchors_dir, exist_ok=True)
saved, failed = [], []
note = ""
if first.get("no_characters"):
    note = "script has no characters; anchors skipped"
else:
    for it in _items:
        d = it["json"]
        if d.get("slug") != slug:
            continue
        if not d.get("ok"):
            failed.append({"char_id": d.get("charId"), "error": (d.get("error") or "")[:200]})
            continue
        png = os.path.join(anchors_dir, "char_%s.png" % d.get("charId"))
        with open(png, "wb") as fh:
            fh.write(base64.b64decode(d["imageB64"]))
        jpg = os.path.join(anchors_dir, "char_%s.jpg" % d.get("charId"))
        r = subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", png,
                            "-vf", "scale='min(768,iw)':-2", "-q:v", "4", jpg],
                           capture_output=True, text=True)
        if r.returncode == 0 and os.path.exists(jpg):
            saved.append(d.get("charId"))
        else:
            failed.append({"char_id": d.get("charId"), "error": (r.stderr or "ffmpeg failed")[-200:]})
    if not saved:
        raise RuntimeError("all character anchors failed: " + json.dumps(failed))
    if failed:
        note = "some anchors failed; affected shots fall back to global refs"
now = datetime.datetime.utcnow().isoformat() + "Z"
pf = os.path.join(root, "project.json")
proj = json.load(open(pf)) if os.path.exists(pf) else {}
proj.setdefault("stages", {})["anchors"] = {"status": "done" if saved else "skipped", "done_at": now, "count": len(saved)}
with open(pf, "w") as fh:
    json.dump(proj, fh, indent=2, ensure_ascii=False)
return [{"json": {"ok": True, "slug": slug, "anchors": saved, "failed": failed, "note": note}}]
